  function daysAgoISO(n) {
    const d = new Date();
    d.setMinutes(d.getMinutes() - d.getTimezoneOffset());
    d.setDate(d.getDate() - n);
    return d.toISOString().slice(0, 10);
  }

  // Birthdays are stored as a full date (so a year can optionally be kept),
  // but "celebrating" only ever compares month + day against today — nobody
  // wants their badge to vanish just because the year on file is old.
  function isBirthdayToday(iso) {
    if (!iso) return false;
    const today = todayISO();
    return iso.slice(5, 10) === today.slice(5, 10);
  }

  // A trainer's own profile only ever stores a birthday (not a raw age
  // number the way client_profiles does) — this derives the age
  // recalcBmrAndTargets needs from it, whole years only, correctly handling
  // "birthday hasn't happened yet this year."
  function ageFromBirthday(iso) {
    if (!iso) return null;
    const b = new Date(iso + "T00:00:00");
    if (isNaN(b.getTime())) return null;
    const now = new Date();
    let age = now.getFullYear() - b.getFullYear();
    const beforeBirthdayThisYear = now.getMonth() < b.getMonth() || (now.getMonth() === b.getMonth() && now.getDate() < b.getDate());
    if (beforeBirthdayThisYear) age--;
    return age;
  }

  // Sept 11 2026, Jimmy: "forget about the cut and why u still putting it!"
