  function isRetiredTemplate(t) {
    return !!(t && typeof t.name === "string" && t.name.trim().toUpperCase().startsWith("[DO NOT USE]"));
  }

  function goalLabel(v) {
    const found = DIET_GOALS.find((g) => g.value === v);
    return found ? found.label : v;
  }

  // Same free-text keyword read used by recalcBmrAndTargets/handleSave below
  // to pick a calorie multiplier from a client's typed-in goal (e.g. "Build
  // muscle, lose fat, get stronger") — pulled out into one shared helper so
