  // screen starts on (Sept 10 2026 — was hardcoded to always start on "Fat
  // loss" regardless of the client's actual stated goal, a real bug: someone
  // trying to bulk got steered toward fat-loss plans by default).
  function dietGoalKeyFromText(text) {
    const g = (text || "").trim().toLowerCase();
    return /lose|cut|fat/.test(g) ? "fat_loss"
      : /gain|bulk|muscle|mass/.test(g) ? "muscle_gain"
      : /recomp|tone/.test(g) ? "recomp"
      : "maintenance";
  }

  // Sum of [protein, carbs, fat] (grams) for a list of {food, grams} entries.
  function mealGenVector(items) {
    let p = 0, c = 0, f = 0;
    items.forEach((it) => {
      const d = MEAL_GEN_FOODS[it.food];
      p += (d.p * it.grams) / 100;
      c += (d.c * it.grams) / 100;
      f += (d.f * it.grams) / 100;
    });
    return [p, c, f];
  }

  function mealGenDet3(m) {
    return m[0][0] * (m[1][1] * m[2][2] - m[1][2] * m[2][1])
      - m[0][1] * (m[1][0] * m[2][2] - m[1][2] * m[2][0])
      + m[0][2] * (m[1][0] * m[2][1] - m[1][1] * m[2][0]);
  }

  // Solve A·x = b where A's columns are the three group vectors (Cramer's rule).
  function mealGenSolve3(cols, b) {
    const M = [
      [cols[0][0], cols[1][0], cols[2][0]],
      [cols[0][1], cols[1][1], cols[2][1]],
      [cols[0][2], cols[1][2], cols[2][2]]
    ];
    const d = mealGenDet3(M);
    const out = [];
    for (let col = 0; col < 3; col++) {
      const Mc = M.map((row) => row.slice());
      for (let row = 0; row < 3; row++) Mc[row][col] = b[row];
      out.push(mealGenDet3(Mc) / d);
    }
    return out; // [kProtein, kCarb, kFat]
  }

  // Grams → display portion, per each food's unit (see MEAL_GEN_FOODS above).
  function mealGenFormatPortion(foodId, grams) {
    const d = MEAL_GEN_FOODS[foodId];
    if (d.unit === "g") return `${Math.round(grams)} g`;
    const count = Math.max(1, Math.round(grams / d.div));
    const unitLabel = d.unit === "eggs" ? (count === 1 ? "egg" : "eggs")
      : d.unit === "whites" ? (count === 1 ? "egg white" : "egg whites")
      : d.unit === "banana" ? (count === 1 ? "banana" : "bananas")
      : d.unit === "scoop" ? (count === 1 ? "scoop" : "scoops")
      : d.unit; // "tsp" reads fine singular or plural
    return `${count} ${unitLabel}`;
  }

  // Works out a lean body mass (kg) from whatever body-composition info a
  // client actually gave, best signal first: body fat % converts to lean
  // mass exactly (weight minus fat), so it wins if present. Muscle mass
  // alone is a rougher stand-in (a smart scale's "muscle mass" reading
  // isn't the same thing as true lean body mass, which also includes
  // bone/organs/water) but it's still a better signal than plain
  // bodyweight, so it's used when that's all the client gave. Returns null
  // if neither was entered — callers fall back to bodyweight-only math.
  function leanMassKgFrom(weightKg, bodyFatPct, muscleMassKg) {
    if (bodyFatPct != null) return weightKg * (1 - bodyFatPct / 100);
    if (muscleMassKg != null) return muscleMassKg;
    return null;
  }

  function inRange(n, range) { return typeof n === "number" && !isNaN(n) && n >= range[0] && n <= range[1]; }

  // Sept 19 2026, Jimmy: JimFit is 18+ only — this was already the declared
  // Google Play "Target audience" (deliberately 18+, not lower, specifically
  // to keep JimFit out of Google's stricter child-safety/family-policy
  // requirements — see jimfit-app-store-roadmap.md) but nothing in the app
  // actually enforced it. Real enforcement point is ProfileGate.commitBirthday
  // below, the one place a real birthday is collected.
  const MIN_SIGNUP_AGE = 18;

  // Shared by every diet-macro form in the app — the per-client plan's meal
  // items (handleSaveMealItem), the ready-plan template's own targets
  // (handleCreateTemplate/handleSaveTemplate), and that template's meal
  // items (handleSaveItem) — all take the same {calories, protein, carbs,
  // fat} shape.
  function macroFieldError(form) {
    if (form.calories !== "" && !inRange(Number(form.calories), DIET_CALORIES_RANGE)) {
      return `Calories should be between ${DIET_CALORIES_RANGE[0]} and ${DIET_CALORIES_RANGE[1]}.`;
    }
    for (const [label, v] of [["Protein", form.protein], ["Carbs", form.carbs], ["Fat", form.fat]]) {
      if (v !== "" && !inRange(Number(v), DIET_MACRO_G_RANGE)) {
        return `${label} should be between ${DIET_MACRO_G_RANGE[0]} and ${DIET_MACRO_G_RANGE[1]}g.`;
      }
    }
    return null;
  }

  // Same, plus the water target — only the ready-plan template form has
  // that field.
  function dietTemplateFieldError(form) {
    const macroErr = macroFieldError(form);
    if (macroErr) return macroErr;
    if (form.water !== "" && !inRange(Number(form.water), DIET_WATER_ML_RANGE)) {
      return `Water target should be between ${DIET_WATER_ML_RANGE[0]} and ${DIET_WATER_ML_RANGE[1]} ml.`;
    }
    return null;
  }

  // BMR from body composition — Katch-McArdle (370 + 21.6 * lean mass) when
  // a lean mass is known, since it's driven by the tissue that actually
  // burns calories at rest rather than total weight, so it doesn't
  // undercount a muscular client or overcount a leaner one the way a
  // weight-only formula does. Falls back to the standard Mifflin-St Jeor
  // formula (weight/height/age/gender only) when no body-fat%/muscle-mass
  // was given — same formula this app has always used for that case.
  function bmrFromBody(weightKg, heightCm, age, gender, leanMassKg) {
    if (leanMassKg != null) return 370 + 21.6 * leanMassKg;
    return gender === "Female" ? 10 * weightKg + 6.25 * heightCm - 5 * age - 161
      : gender === "Male" ? 10 * weightKg + 6.25 * heightCm - 5 * age + 5
      : 10 * weightKg + 6.25 * heightCm - 5 * age - 78;
  }

  // Splits a calorie target into Calories/Protein/Carbs/Fat. Protein tracks
  // lean mass when it's known (2.2g/kg lean mass — muscle tissue is what
  // actually needs the protein, so this is more accurate for anyone
  // visibly muscular or visibly lean than a flat per-kg-bodyweight number),
  // falling back to bodyweight (2g/kg, 1.6g/kg if Female — women typically
  // carry a higher body-fat baseline so a slightly lower protein-per-kg
  // target still lands in a sensible range) when no body-fat%/muscle-mass
  // was given. Fat is 25% of calories either way, and carbs take whatever
  // calories are left over.
  // Standard sports-nutrition rule of thumb (35 ml per kg bodyweight) — used
  // any time a water target gets auto-calculated alongside calories/macros,
  // since without a water target set the water-logging card on the Diet tab
  // has nothing to measure against and stays hidden entirely (Sept 6 2026 —
  // Jimmy: "i also want to see the water log" — a self-train client with an
  // auto-calculated calorie/macro plan never got a water target, so she had
  // no way to log water at all).
  function waterTargetMlFromWeight(weightKg) {
    return Math.round((weightKg || 70) * 35);
  }

  function macroTargetsFromCalories(calories, bodyWeightKg, gender, leanMassKg) {
    const protein = leanMassKg != null
      ? Math.round(2.2 * leanMassKg)
      : Math.round((gender === "Female" ? 1.6 : 2) * (bodyWeightKg || 0));
    const fat = Math.round((calories * 0.25) / 9);
    const carbs = Math.max(0, Math.round((calories - protein * 4 - fat * 9) / 4));
    return { calories: Math.round(calories), protein, carbs, fat };
  }

  // Sept 9 2026, round 4: Jimmy changed Bugz's weight (75kg -> 62kg) through
  // "Edit profile" and the BMR tile stayed frozen at the same number either
  // way — a regression from the round-3 fix just below. That fix made
  // "the latest row with a real bmr on it" always win over the formula, so
  // profile edits could never overwrite a manual BMR again — exactly what
  // Jimmy asked for, but it turned out there's a SECOND kind of
  // auto-generated row this app writes that the note filter never caught:
  // the very first row created at signup carries its own distinct note
  // ("Auto-calculated from your signup info...", not "Auto-recalculated
  // after a profile update"), so it looked "manual" to every filter above
  // and permanently pinned BMR at whatever it was on day one — no amount of
  // later weight/height/age edits could ever move it again. Both
  // auto-generated note strings are collected here, in ONE place, instead
  // of being matched ad hoc inside separate SQL filters scattered across
  // several functions — the earlier bug is exactly the kind of thing that
  // happens when the same marker text has to be kept in sync by hand in
  // more than one spot. `fetchAssessmentHistory` below fetches a client's
  // rows ONCE (plain, no per-field SQL filtering) and every consumer below
  // does its "manual vs auto" matching against that same array in plain
  // JS, which also sidesteps the SQL NULL-comparison trap that broke the
  // very first version of this fix (Sept 9 2026, round 2) — no filter
  // string to get subtly wrong a third time.
  const AUTO_ASSESSMENT_NOTES = [
    "Auto-recalculated after a profile update",
    "Auto-calculated from your signup info (height, weight, age)"
  ];

  function isAutoAssessmentNote(note) {
    return !!note && AUTO_ASSESSMENT_NOTES.includes(note);
  }

  // A self-train (no trainer) client has app access if either their 14-day
  // trial hasn't ended yet, or a manager has marked them paid through a date
  // that hasn't passed yet. Anyone with a real trainer never goes through
  // this check at all — see isSelfTrainClient at each call site.
  function hasSelfTrainAppAccess(profile) {
    if (!profile) return false;
    const now = new Date();
    if (profile.trial_ends_at && new Date(profile.trial_ends_at) > now) return true;
    if (profile.access_paid_through) {
      const paidThrough = new Date(profile.access_paid_through + "T23:59:59");
      if (paidThrough > now) return true;
    }
    return false;
  }

  // Stricter than hasSelfTrainAppAccess above: true ONLY once a manager has
  // actually marked the $10/month as paid — being inside the free 14-day
  // trial is never enough here. Jimmy's call (Sept 5 2026): a self-train
  // client shouldn't be able to buy a $35 program or $30 diet plan while
  // dodging the recurring $10/month subscription, so purchase actions (not
  // Log/Diet access, which stays trial-friendly) are gated on this instead
  // of hasSelfTrainAppAccess.
  function hasSelfTrainPaidAccess(profile) {
    if (!profile || !profile.access_paid_through) return false;
    const paidThrough = new Date(profile.access_paid_through + "T23:59:59");
    return paidThrough > new Date();
  }

  const PREF_KEY = "strain-log-prefs";

  const NAME_KEY = "strain-log-client-name";

  // Sept 13 2026, Jimmy: "when i refresh any where on the tab to keep me on
  // the same page after refresh not to the beginning" — which bottom-nav
  // tab (and sub-tab, for Diet/Progress) is open now survives a refresh,
  // same persisted-to-localStorage pattern THEME_KEY already uses just
  // above. One set of keys for the client app shell (TrainingLog), one for
  // the trainer/manager shell (TrainerView) since they're separate
  // components with their own independent tab state.
  const CLIENT_TAB_KEY = "jimfit-client-tab";

  const CLIENT_DIET_SUBTAB_KEY = "jimfit-client-diet-subtab";

  const CLIENT_PROGRESS_SUBTAB_KEY = "jimfit-client-progress-subtab";

  const CLIENT_PROGRAMS_SUBTAB_KEY = "jimfit-client-programs-subtab";

  const TRAINER_TAB_KEY = "jimfit-trainer-tab";

  function computeGrouped(entries, titleFilter, dateFilter) {
    let filtered = entries;
    if (titleFilter && titleFilter !== "All") {
      filtered = titleFilter === "__untitled__"
        ? filtered.filter((x) => !(x.workoutTitle || "").trim())
        : filtered.filter((x) => (x.workoutTitle || "").trim() === titleFilter);
    }
    if (!dateFilter || dateFilter === "none") {
      filtered = [];
    } else if (dateFilter !== "All") {
      filtered = filtered.filter((x) => x.date === dateFilter);
    }
    const byDate = {};
    filtered.forEach((x) => { (byDate[x.date] = byDate[x.date] || []).push(x); });
    return Object.entries(byDate).sort((a, b) => (a[0] < b[0] ? 1 : -1));
  }

  // Within one day's entries, cluster consecutive/logged exercises by the workout
  // title they were saved under (e.g. "Push", "Legs"). Untitled entries (no title
  // set when logged) come back under the "" key and render without a subheader.
  function groupByTitle(list) {
    const order = [];
    const map = {};
    list.forEach((x) => {
      const key = (x.workoutTitle || "").trim();
      if (!map[key]) { map[key] = []; order.push(key); }
      map[key].push(x);
    });
    return order.map((k) => [k, map[k]]);
  }

  // Keyed by exerciseGifKey (trim + lowercase), NOT the raw typed name — so
  // "Bench Press" and "bench press" (or a stray trailing space) are tracked
  // as the one exercise they actually are, instead of silently splitting a
  // client's real record into two separate, incomplete ones. Callers must
  // look up with exerciseGifKey(entry.exercise) to match.
  function computeMaxWeightByExercise(entries) {
    const map = {};
    entries.forEach((x) => x.sets.forEach((s) => {
      const key = exerciseGifKey(x.exercise);
      if (!key) return;
      const w = Number(s.weight) || 0;
      if (!map[key] || w > map[key]) map[key] = w;
    }));
    return map;
  }

  function volumeInRange(entries, startDaysAgo, endDaysAgo) {
    const start = new Date(); start.setDate(start.getDate() - startDaysAgo);
    const end = new Date(); end.setDate(end.getDate() - endDaysAgo);
    let vol = 0;
    entries.forEach((x) => {
      const d = new Date(x.date);
      if (d >= start && d < end) x.sets.forEach((s) => { vol += (Number(s.reps) || 0) * (Number(s.weight) || 0); });
    });
    return Math.round(vol);
  }

  function computeWeekVolume(entries) { return volumeInRange(entries, 7, 0); }

  function computePrevWeekVolume(entries) { return volumeInRange(entries, 14, 7); }

  function estimateWorkoutDurationMinutes(dayEntries) {
    let totalSeconds = 0;
    (dayEntries || []).forEach((x) => {
      (x.sets || []).forEach((s) => {
        totalSeconds += SECONDS_PER_SET_UNDER_TENSION + (Number(s.rest) || DEFAULT_REST_SECONDS);
      });
    });
    return totalSeconds / 60;
  }

  function estimateWorkoutCalories(dayEntries, weightKg) {
    if (!dayEntries || !dayEntries.length || !weightKg) return 0;
    const minutes = estimateWorkoutDurationMinutes(dayEntries);
    // kcal/min = MET × 3.5 × weight(kg) / 200 — the standard MET-to-calorie conversion.
    const kcalPerMin = (RESISTANCE_TRAINING_MET * 3.5 * weightKg) / 200;
    return Math.round(kcalPerMin * minutes);
  }

  // ~0.0005 kcal per step per kg of bodyweight — lands around 30-40 kcal per 1,000
  // steps for an average adult, roughly in line with published step-based calorie
  // estimates. Also an estimate, not a measured value.
  function estimateStepCalories(steps, weightKg) {
    if (!steps || !weightKg) return 0;
    return Math.round(steps * weightKg * 0.0005);
  }

  // Same rolling-7-day window as the header's "7-day volume" tile, but
  // returning the entries themselves (for the weekly muscle-balance view)
  // instead of a single summed number.
  function entriesInLastDays(entries, days) {
    const start = new Date(); start.setDate(start.getDate() - days);
    const end = new Date(); end.setHours(23, 59, 59, 999);
    return entries.filter((x) => { const d = new Date(x.date); return d >= start && d <= end; });
  }

  function sessionsInRange(entries, daysAgo) {
    const start = new Date(); start.setDate(start.getDate() - daysAgo);
    const end = new Date(); end.setHours(23, 59, 59, 999);
    const dates = new Set();
    entries.forEach((x) => { const d = new Date(x.date); if (d >= start && d <= end) dates.add(x.date); });
    return dates.size;
  }

  function computeWeekSessions(entries) { return sessionsInRange(entries, 7); }

  function computeMonthSessions(entries) { return sessionsInRange(entries, 30); }

  // How many CONSECUTIVE, fully-completed rolling 7-day windows a client has
  // hit their weekly session goal in, counting backward from the most recent
  // completed window. Deliberately skips the current, still-in-progress week
  // (that one's covered separately by the "This week" card above) so the
  // streak never looks broken just because the week isn't over yet.
  function computeWeekStreak(entries, daysPerWeek) {
    if (!daysPerWeek) return 0;
    let streak = 0;
    for (let w = 1; w <= 52; w++) {
      const count = sessionsInRangeWindow(entries, (w + 1) * 7, w * 7);
      if (count >= daysPerWeek) streak++;
      else break;
    }
    return streak;
  }

  function sessionsInRangeWindow(entries, startDaysAgo, endDaysAgo) {
    const start = new Date(); start.setDate(start.getDate() - startDaysAgo);
    const end = new Date(); end.setDate(end.getDate() - endDaysAgo);
    const dates = new Set();
    entries.forEach((x) => { const d = new Date(x.date); if (d >= start && d < end) dates.add(x.date); });
    return dates.size;
  }

  // Every exercise's current all-time best top-set weight, plus the date it
  // was first hit — separate from computeMaxWeightByExercise (which only
  // needs the number for the sparkle-chip check) because a "since <date>"
  // history is what actually makes a personal-records list feel earned.
  function computePersonalRecords(entries) {
    // Group by exerciseGifKey (trim + lowercase), not the raw typed name — a
    // client who logs "Bench Press" one day and "Bench press" the next is
    // still doing the same exercise, and their record has to reflect both
    // sessions together or it silently understates their real best.
    const byExercise = {};
    entries.forEach((x) => {
      const key = exerciseGifKey(x.exercise);
      if (!key) return;
      (byExercise[key] = byExercise[key] || []).push(x);
    });
    const records = [];
    Object.keys(byExercise).forEach((key) => {
      const list = byExercise[key].slice().sort((a, b) => (a.date < b.date ? -1 : a.date > b.date ? 1 : 0));
      let best = 0, bestDate = null, muscleGroup = "Full Body", exercise = list[0].exercise;
      list.forEach((x) => {
        muscleGroup = x.muscleGroup || muscleGroup;
        exercise = x.exercise || exercise; // show whichever casing was typed most recently
        const topWeight = Math.max(0, ...x.sets.map((s) => Number(s.weight) || 0));
        if (topWeight > best) { best = topWeight; bestDate = x.date; }
      });
      if (best > 0) records.push({ exercise, muscleGroup, weight: best, date: bestDate });
    });
    return records.sort((a, b) => (a.date < b.date ? 1 : a.date > b.date ? -1 : 0));
  }

  // Same local-timezone convention as todayISO — a plain `.toISOString()`
  // would silently shift a date back a day for anyone west of UTC.
  function dateToISO(d) {
    const copy = new Date(d);
    copy.setMinutes(copy.getMinutes() - copy.getTimezoneOffset());
    return copy.toISOString().slice(0, 10);
  }

  function daysSince(iso) {
    if (!iso) return null;
    const d = new Date(iso + "T00:00:00");
    const now = new Date(todayISO() + "T00:00:00");
    return Math.round((now - d) / 86400000);
  }

  // ---- training calendar heatmap ----
  // GitHub-contributions-style grid: one column per week, one cell per day,
  // shaded by that day's total volume. Weeks always start on Sunday so the
  // grid lines up cleanly regardless of what day "today" happens to be.
  function computeTrainingHeatmap(entries, weeks = 14) {
    const byDate = {};
    entries.forEach((x) => {
      const vol = x.sets.reduce((acc, s) => acc + (Number(s.reps) || 0) * (Number(s.weight) || 0), 0);
      byDate[x.date] = (byDate[x.date] || 0) + vol;
    });
    const today = new Date(todayISO() + "T00:00:00");
    const start = new Date(today);
    start.setDate(start.getDate() - (weeks * 7 - 1));
    start.setDate(start.getDate() - start.getDay()); // snap back to the preceding Sunday
    const end = new Date(today);
    end.setDate(end.getDate() + (6 - end.getDay())); // pad forward to the following Saturday, so every column is a full 7 cells
    const cells = [];
    const cur = new Date(start);
    while (cur <= end) {
      const iso = dateToISO(cur);
      cells.push({ date: iso, volume: byDate[iso] || 0, future: cur > today });
      cur.setDate(cur.getDate() + 1);
    }
    const maxVol = Math.max(1, ...cells.map((c) => c.volume));
    cells.forEach((c) => { c.level = c.volume <= 0 ? 0 : Math.min(4, Math.ceil((c.volume / maxVol) * 4)); });
    const weeksArr = [];
    for (let i = 0; i < cells.length; i += 7) weeksArr.push(cells.slice(i, i + 7));
    return weeksArr;
  }

  // ---- milestone badges ----
  // Consistency and tenure milestones — separate from Personal Records
  // (which is about strength numbers) so a client who shows up reliably but
  // isn't chasing new PRs every week still has something to feel good about.
  const SESSION_MILESTONES = [10, 25, 50, 100, 200, 500];

  const MONTH_MILESTONES = [1, 3, 6, 12, 24];

  function computeMilestones(entries) {
    if (!entries.length) return null;
    const totalSessions = new Set(entries.map((x) => x.date)).size;
    const firstDate = entries.reduce((min, x) => (x.date < min ? x.date : min), entries[0].date);
    const monthsActive = Math.floor(daysSince(firstDate) / 30);
    const sessionMilestone = SESSION_MILESTONES.filter((m) => totalSessions >= m).pop() || null;
    const monthMilestone = MONTH_MILESTONES.filter((m) => monthsActive >= m).pop() || null;
    if (!sessionMilestone && !monthMilestone) return null;
    return { totalSessions, sessionMilestone, monthsActive, monthMilestone, firstDate };
  }

  // Live progress for the CURRENT calendar week (Mon–Sun, today included) —
  // separate from computeWeeklyRecap, which deliberately only ever judges a
  // week once it's fully over. This is what lets "Missed goal" not get
  // confused with "still has days left to hit it this week."
  function computeWeekToDate(entries, daysPerWeek) {
    const today = new Date(todayISO() + "T00:00:00");
    const dow = today.getDay(); // 0 = Sun .. 6 = Sat
    const mondayOffset = (dow + 6) % 7; // days since this week's Monday
    const weekStart = new Date(today); weekStart.setDate(weekStart.getDate() - mondayOffset);
    const weekEnd = new Date(weekStart); weekEnd.setDate(weekEnd.getDate() + 6);
    const inRange = entries.filter((x) => { const d = new Date(x.date + "T00:00:00"); return d >= weekStart && d <= today; });
    const trainedDates = new Set(inRange.map((x) => x.date));
    const sessions = trainedDates.size;
    const days = [];
    for (const dt = new Date(weekStart); dt <= weekEnd; dt.setDate(dt.getDate() + 1)) {
      const iso = dateToISO(dt);
      const isFuture = dt > today;
      days.push({ date: iso, label: dt.toLocaleDateString("en-US", { weekday: "narrow" }), trained: !isFuture && trainedDates.has(iso), isFuture, isToday: iso === todayISO() });
    }
    const daysLeft = 6 - mondayOffset; // days remaining after today, through Sunday
    return { start: dateToISO(weekStart), end: dateToISO(weekEnd), sessions, daysPerWeek: daysPerWeek || null, daysLeft, days };
  }

  function clientRiskLabel(lastDate) {
    if (!lastDate) return "Never logged";
    const days = daysSince(lastDate);
    if (days != null && days >= AT_RISK_DAYS) return `Inactive ${days}d`;
    return null;
  }

  function computeDashboardStats(entries, payments) {
    const today = todayISO();
    const monthPrefix = today.slice(0, 7);
    const todaySet = new Set();
    const monthSet = new Set();
    entries.forEach((x) => {
      if (!x.date) return;
      // Sept 18 2026: was keyed by clientName + date — two clients sharing
      // a first name (normal pooling 17 trainers' rosters together) counted
      // as ONE session instead of two, silently undercounting the numbers
      // this feeds up to the Dashboard/higher management. Every real
      // account has a real, unique clientId, so that's the key whenever
      // it's there; clientName stays as the fallback only for old/self-log
      // entries that genuinely have no clientId, same as elsewhere in the app.
      const who = x.clientId || x.clientName;
      if (x.date === today) todaySet.add(who + "|" + x.date);
      if (x.date.slice(0, 7) === monthPrefix) monthSet.add(who + "|" + x.date);
    });
    let totalPaid = 0, monthPaid = 0;
    payments.forEach((p) => {
      const amt = Number(p.amount) || 0;
      totalPaid += amt;
      if (p.paid_on && p.paid_on.slice(0, 7) === monthPrefix) monthPaid += amt;
    });
    return { sessionsToday: todaySet.size, sessionsMonth: monthSet.size, totalPaid, monthPaid };
  }

  function computeMonthlyBreakdown(entries, payments) {
    const sessionsByMonth = {};
    entries.forEach((x) => {
      if (!x.date) return;
      // Sept 18 2026: same clientId-first fix as computeDashboardStats above.
      const who = x.clientId || x.clientName;
      const m = x.date.slice(0, 7);
      const set = sessionsByMonth[m] || (sessionsByMonth[m] = new Set());
      set.add(who + "|" + x.date);
    });
    const paidByMonth = {};
    payments.forEach((p) => {
      if (!p.paid_on) return;
      const m = p.paid_on.slice(0, 7);
      paidByMonth[m] = (paidByMonth[m] || 0) + (Number(p.amount) || 0);
    });
    const months = new Set([...Object.keys(sessionsByMonth), ...Object.keys(paidByMonth)]);
    return Array.from(months).sort((a, b) => (a < b ? 1 : -1)).map((m) => ({
      month: m,
      sessions: sessionsByMonth[m] ? sessionsByMonth[m].size : 0,
      paid: paidByMonth[m] || 0
    }));
  }

  // Sept 9 2026, Jimmy: "instead of 7 days can we make it also from which
  // date till which date we can choose in calendar? and without of the all
  // time" — the fixed "Last 7 days" / "All time" toggle is gone; statsRange
  // is now a { from, to } pair of ISO dates the person picks themselves via
  // two calendar inputs (see StatsPanel below). Plain string comparison
  // works fine since dates are always "YYYY-MM-DD".
  function computeMuscleVolume(entries, statsRange, statsMetric) {
    const from = statsRange && statsRange.from;
    const to = statsRange && statsRange.to;
    const totals = {}, setCounts = {};
    MUSCLE_GROUPS.forEach((m) => { totals[m] = 0; setCounts[m] = 0; });
    entries.forEach((x) => {
      if (from && x.date < from) return;
      if (to && x.date > to) return;
      const mg = x.muscleGroup || "Full Body";
      const entryVol = x.sets.reduce((acc, s) => acc + (Number(s.reps) || 0) * (Number(s.weight) || 0), 0);
      totals[mg] = (totals[mg] || 0) + entryVol;
      setCounts[mg] = (setCounts[mg] || 0) + x.sets.length;
    });
    return MUSCLE_GROUPS.map((m) => ({ muscle: m, volume: Math.round(totals[m] || 0), sets: setCounts[m] || 0 }))
      .filter((x) => x.volume > 0 || x.sets > 0)
      .sort((a, b) => statsMetric === "sets" ? b.sets - a.sets : b.volume - a.volume);
  }

  // Per-exercise strength trend: one top-set weight per day, across every session ever
  // logged for that exercise (independent of the week/all-time toggle, which is about
  // muscle volume, not long-run trend) — each date stays its own point, never merged.
  function computeExerciseProgression(entries) {
    // Same case/whitespace normalization as computeMaxWeightByExercise and
    // computePersonalRecords — grouped by exerciseGifKey so "Bench Press" and
    // "Bench press" plot as one continuous trend line, not two broken ones.
    const byExercise = {};
    entries.forEach((x) => {
      const key = exerciseGifKey(x.exercise);
      if (!key) return;
      const topWeight = Math.max(0, ...x.sets.map((s) => Number(s.weight) || 0));
      (byExercise[key] = byExercise[key] || { exercise: x.exercise, muscleGroup: x.muscleGroup, byDate: {} });
      byExercise[key].exercise = x.exercise || byExercise[key].exercise; // most-recent casing wins for display
      byExercise[key].muscleGroup = x.muscleGroup || byExercise[key].muscleGroup;
      const cur = byExercise[key].byDate[x.date];
      byExercise[key].byDate[x.date] = cur === undefined ? topWeight : Math.max(cur, topWeight);
    });
    return Object.values(byExercise).map((info) => {
      const points = Object.entries(info.byDate).sort((a, b) => (a[0] < b[0] ? -1 : 1)).map(([date, weight]) => ({ date, weight }));
      return { exercise: info.exercise, muscleGroup: info.muscleGroup || "Full Body", points };
    }).filter((x) => x.points.length >= 2)
      .sort((a, b) => b.points.length - a.points.length || a.exercise.localeCompare(b.exercise));
  }

  function progressionDelta(points, unit) {
    const first = points[0].weight, last = points[points.length - 1].weight;
    if (first > 0) {
      const pct = Math.round(((last - first) / first) * 100);
      if (pct === 0) return { dir: "flat", text: "flat" };
      return { dir: pct > 0 ? "up" : "down", text: `${pct > 0 ? "+" : ""}${pct}%` };
    }
    const diff = Math.round((last - first) * 10) / 10;
    if (diff === 0) return { dir: "flat", text: "flat" };
    return { dir: diff > 0 ? "up" : "down", text: `${diff > 0 ? "+" : ""}${diff}${unit}` };
  }

  function sparklineGeometry(points, w, h, pad) {
    const weights = points.map((p) => p.weight);
    const min = Math.min(...weights), max = Math.max(...weights);
    const range = max - min || 1;
    const n = points.length;
    const stepX = n > 1 ? (w - 2 * pad) / (n - 1) : 0;
    return points.map((p, i) => [pad + i * stepX, pad + (h - 2 * pad) * (1 - (p.weight - min) / range)]);
  }

  // Sept 18 2026: same idea as sparklineGeometry above but reading a plain
  // `value` field instead of a hardcoded `.weight`, so one geometry helper
  // works for any numeric metric (used by MetricTrendCard below for both
  // AssessmentPanel and MeasurementsPanel's new trend views). Left
  // sparklineGeometry itself untouched — ProgressCard's exercise-progression
  // sparklines already depend on its exact `.weight` shape.
  function trendGeometry(values, w, h, pad) {
    const min = Math.min(...values), max = Math.max(...values);
    const range = max - min || 1;
    const n = values.length;
    const stepX = n > 1 ? (w - 2 * pad) / (n - 1) : 0;
    return values.map((v, i) => [pad + i * stepX, pad + (h - 2 * pad) * (1 - (v - min) / range)]);
  }

  // Records a short voice note (English or Lebanese Arabic, mixed is fine), sends it to the
  // voice-transcribe Edge Function (OpenAI speech-to-text), and hands the transcribed text back
  // to the caller via onTranscribed — it never saves anything itself. The caller always drops the
  // text into a normal editable field so the person can fix any mis-heard word before saving,
  // same safety net as typing it by hand.
  // Pulls the first number out of a spoken phrase like "twenty nine" or "I'm 82 kilos" so a mic
  // button next to a plain number field can be used too — speech models transcribe spoken numbers
  // as digits almost always, so a simple digit-scan covers the vast majority of real phrases.
  function extractSpokenNumber(text) {
    if (!text) return "";
    const match = String(text).match(/\d+(\.\d+)?/);
    return match ? match[0] : "";
  }

  // Same idea as extractSpokenNumber but pulls every number out — used by the
  // "Height & weight?" onboarding step, which asks for both in one "Speak"
  // (e.g. "I'm 178 cm and 82 kilos" -> ["178", "82"]).
  function extractSpokenNumbers(text) {
    if (!text) return [];
    return String(text).match(/\d+(\.\d+)?/g) || [];
  }

  function blobToBase64(blob) {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.onloadend = () => {
        const result = String(reader.result || "");
        resolve(result.split(",")[1] || "");
      };
      reader.onerror = reject;
      reader.readAsDataURL(blob);
    });
  }

  // Sept 15 2026, Jimmy: "can i add here one speaker for all?" — the Info
  // tab's Personal/Body/Training fields each had their own little mic button
  // (inside EditableStat's editing state), so filling in a new client's info
  // meant tapping into every single field to say one value at a time. Same
  // "one button replaces many" move as SmartVoiceEntryButton above did for
  // the New Exercise form: say it all in one breath — name, age, birthday,
  // gender, phone, height, weight, days/week, goal, any order, any language —
  // and every field mentioned fills in at once. Anything left unmentioned is
  // simply left alone, never cleared. Talks to a new "voice-profile-entry"
  // Supabase Edge Function (same translate-then-structure pattern as
  // voice-log-entry, just a different field schema). Sits once above the
  // Personal/Body/Training cards on all three Info screens (client's own
  // "My info", trainer's client detail, manager's client detail) — Jimmy
  // asked for it on those three sections specifically, not Health, which
  // already has its own structured add-entry flow via ClientInjuriesPanel.
  // The old per-field mics on the specific fields this replaced (Name, Last
  // name, Age, Phone/WhatsApp, Height, Weight, Goal) are hidden via
  // EditableStat's new `hideMic` prop — every other EditableStat in the app
  // (trainer profile fields, billing notes, etc.) keeps its own mic as-is.
  const PROFILE_VOICE_FIELD_LABELS = {
    client_name: "Name", last_name: "Last name", age: "Age", birthday: "Birthday",
    gender: "Gender", phone: "Phone", height_cm: "Height", weight_kg: "Weight",
    days_per_week: "Trains/week", goal: "Goal"
  };

  function detectMoodEmoji(text) {
    if (!text) return null;
    const t = text.toLowerCase();
    for (let i = 0; i < MOOD_EMOJI_KEYWORDS.length; i++) {
      const { emoji, words } = MOOD_EMOJI_KEYWORDS[i];
      if (words.some((w) => t.includes(w))) return emoji;
    }
    return null;
  }

  // ---- exercise demo animations ----
  // Free, keyless lookup against the "free-exercise-db" open dataset (public domain / Unlicense,
  // safe for a paid or resold product) — 873 exercises, each with two position photos we flip
  // between to fake a simple animation. It's one plain JSON file (no flaky paginated API), so
  // it's pulled into our own Supabase table (exercise_catalog) ONE TIME EVER — whoever taps
  // "Show demo" first triggers it, everyone after just reads from our own table — and matched
  // by name ourselves. Results are cached in Supabase (table: exercise_gifs) so we only ever
  // look an exercise name up once, and a trainer/manager can paste their own link to override.
  const exerciseGifMemCache = {};

  function exerciseGifKey(name) {
    return (name || "").trim().toLowerCase();
  }

  // Try the name as typed, then a naive singular/plural flip of its last word
  // ("Squats" <-> "Squat"), so a trainer typing either form still finds a match.
  function exerciseSearchVariants(name) {
    const trimmed = (name || "").trim();
    if (!trimmed) return [];
    const words = trimmed.split(/\s+/);
    const last = words[words.length - 1];
    const flipped = /s$/i.test(last) && last.length > 1
      ? [...words.slice(0, -1), last.slice(0, -1)].join(" ")
      : [...words.slice(0, -1), last + "s"].join(" ");
    return flipped.toLowerCase() === trimmed.toLowerCase() ? [trimmed] : [trimmed, flipped];
  }

  // Sept 13 2026: strips a trailing qualifier ("Barbell Bench Press - Medium
  // Grip" -> "Barbell Bench Press", "Cable Fly (Low to High)" -> "Cable Fly")
  // so a name a smaller catalog doesn't have the exact variant for can still
  // fall back to matching its base exercise. Returns null when there's no
  // qualifier to strip (name is already "base").
  function exerciseBaseName(name) {
    const trimmed = (name || "").trim();
    if (!trimmed) return null;
    const dashIdx = trimmed.search(/\s[-–]\s/);
    const parenIdx = trimmed.indexOf("(");
    let cut = -1;
    if (dashIdx >= 0) cut = dashIdx;
    if (parenIdx >= 0 && (cut < 0 || parenIdx < cut)) cut = parenIdx;
    if (cut <= 0) return null;
    const base = trimmed.slice(0, cut).trim();
    return base && base.toLowerCase() !== trimmed.toLowerCase() ? base : null;
  }

  const FREE_EXERCISE_DB_JSON = "https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/dist/exercises.json";

  const FREE_EXERCISE_DB_IMAGE_BASE = "https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/";

  function guessMuscleGroupFromPrimary(primaryMuscle) {
    return PRIMARY_MUSCLE_TO_GROUP[(primaryMuscle || "").toLowerCase()] || "Full Body";
  }

  function basicExerciseRank(name, muscleKey) {
    const keywords = BASIC_EXERCISE_KEYWORDS_BY_MUSCLE[muscleKey];
    if (!keywords || !keywords.length) return 0; // no curated list for this muscle — leave order untouched (all tie, sort falls back to alphabetical)
    const n = (name || "").toLowerCase();
    for (let i = 0; i < keywords.length; i++) { if (n.includes(keywords[i])) return i; }
    return keywords.length; // not one of the basics — after all of them, alphabetical among themselves
  }

  function sortExercisesByPopularity(names, muscleKey) {
    return names.slice().sort((a, b) => {
      const ra = basicExerciseRank(a, muscleKey), rb = basicExerciseRank(b, muscleKey);
      return ra !== rb ? ra - rb : a.localeCompare(b);
    });
  }

  // ---- consistent exercise icons (RepDB) ----
  // Jimmy: "instead of demo exercises can i put a pics like that moving all
  // to be the same for each exercise" — reacting to a competitor app (Hevy)
  // where every exercise shows a small, ALWAYS-VISIBLE icon in one consistent
  // illustration style, instead of this app's "Show demo" flip through a real
  // stock photo. Deliberately a separate, parallel system from the
  // free-exercise-db "Show demo" flow above — that flow's manual-link
  // override, muscle tagging, and YouTube fallback are untouched; this just
  // adds a small consistent-style icon next to an exercise's name.
  //
  // Source: RepDB's free exercise dataset (repdb.co) — 601 exercises, one
  // consistent flat-illustration art style, free for commercial in-app use
  // with attribution (a visible "Exercise data by RepDB" credit — see the
  // link on the welcome screen).
  const REPDB_JSON_URL = "https://raw.githubusercontent.com/RepDB/exercise-dataset/main/exercises.json";

  const REPDB_IMAGE_BASE = "https://raw.githubusercontent.com/RepDB/exercise-dataset/main/";

  const exerciseIconMemCache = {};

  function exerciseHasDemoSync(name, repdbNameSet) {
    if (!repdbNameSet || !repdbNameSet.size) return false;
    const key = exerciseGifKey(name);
    if (!key) return false;
    if (repdbNameSet.has(key)) return true;
    const base = exerciseBaseName(name);
    return !!(base && repdbNameSet.has(exerciseGifKey(base)));
  }

  // Sept 13 2026, Jimmy: "still the old way" — the small icon above was live,
  // but tapping "Show demo" still opened the old real stock photo, which
  // looked out of place next to the new consistent icon. This picks what
  // ExerciseDemo's big picture actually shows: a trainer's own manually-added
  // link always wins (same exercise_gifs table/flow as before — trainers can
  // still fix a wrong match), but the automatic default is now the same
  // consistent RepDB icon everywhere else, instead of the old free-exercise-db
  // real photo. Deliberately checks matched_name === null to tell "a trainer
  // picked this on purpose" apart from "the old auto-matcher found this" —
  // rows from before this switch have a matched_name set and are skipped so
  // they don't keep showing the retired real-photo system.
  const exerciseDemoVisualMemCache = {};

  // ---- exercise muscle-highlight diagram ----
  // Same free-exercise-db sync already powering the demo photos also carries
  // primaryMuscles/secondaryMuscles per exercise — this just reads that data
  // back out and draws it as a simple front/back body diagram instead of a
  // custom illustration per exercise, so it scales to the whole 873-exercise
  // catalog for free. Separate small cache from the gif lookup on purpose:
  // a trainer's manual gif-link override (stored in exercise_gifs) should
  // never short-circuit the muscle lookup, which always comes from the
  // catalog itself.
  const exerciseMusclesMemCache = {};

  function youtubeEmbedUrl(url) {
    if (!url) return null;
    const m = url.match(/(?:youtube\.com\/watch\?v=|youtu\.be\/|youtube\.com\/shorts\/|youtube\.com\/embed\/)([a-zA-Z0-9_-]{6,})/);
    return m ? `https://www.youtube.com/embed/${m[1]}` : null;
  }

  // One-click jump to a pre-filled YouTube search for an exercise with no demo
  // yet, so finding a video is "click, pick the best result, copy the link"
  // instead of opening YouTube and typing the name in yourself every time.
  function youtubeSearchUrl(name) {
    return `https://www.youtube.com/results?search_query=${encodeURIComponent((name || "").trim() + " exercise tutorial")}`;
  }

  // Owner-facing screen: every distinct exercise name used anywhere across
  // programs and logged workouts, in one list, with its demo status — so
  // filling in the gaps doesn't mean hunting through every program one at a
  // time. Reuses the exact same lookup/caching "Show demo" uses everywhere
  // else, so what this screen reports always matches what a trainer or
  // client actually sees when they tap "Show demo" themselves.
  // Splits a pasted line into "everything before the link" (the exercise name)
  // and the link itself, by locating the URL rather than guessing a delimiter —
  // so it works whether the manager typed "Squat - https://…", "Squat: https://…",
  // "Squat, https://…", or pasted a tab-separated row straight out of a spreadsheet.
  function parseBulkExerciseLines(text) {
    return (text || "")
      .split("\n")
      .map((line) => line.trim())
      .filter(Boolean)
      .map((raw) => {
        const m = raw.match(/^(.*?)[\s:,\-|]*?(https?:\/\/\S+)\s*$/i);
        if (!m) return { raw, name: null, url: null };
        const name = m[1].replace(/[\s:,\-|]+$/, "").trim();
        const url = m[2].trim();
        return { raw, name: name || null, url };
      });
  }

  // Lets a trainer/owner log (or edit/delete) a workout entry on a specific client's behalf,
  // from that client's own detail page — same Date → Workout title → Exercise → Sets flow as
  // the client's own self-log form, just bound to `clientName` instead of the logged-in user.
  // Adapts a top-level `setAllEntries` (which holds every client's entries mixed together) into
  // a `setEntries` that ClientLogPanel can call as if it only ever saw one client's entries.
  // targetClientId (a real client_profiles.id) is preferred whenever it's
  // known — two clients can share a display name, and matching by name alone
  // would fold a same-named client's entries into this update (or drop this
  // client's own entries out of it). Only falls back to name matching for a
